// HasHotelOffer applies the HasEdge predicate on the "hotel_offer" edge.
func HasHotelOffer() predicate.TravelOrder {
	return predicate.TravelOrder(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, HotelOfferTable, HotelOfferColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasHotelOfferWith applies the HasEdge predicate on the "hotel_offer" edge with a given conditions (other predicates).
func HasHotelOfferWith(preds ...predicate.HotelOffer) predicate.TravelOrder {
	return predicate.TravelOrder(func(s *sql.Selector) {
		step := newHotelOfferStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

