// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TravelOrder) predicate.TravelOrder {
	return predicate.TravelOrder(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TravelOrder) predicate.TravelOrder {
	return predicate.TravelOrder(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TravelOrder) predicate.TravelOrder {
	return predicate.TravelOrder(sql.NotPredicates(p))
}
